llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "In humans, oral lycopene—a large, highly lipophilic isoprenoid with no ionizable groups—showed only 0.17% systemic availability, directly demonstrating that this physicochemical class can have very low oral bioavailability; other human lycopene studies similarly report ~1–3%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Isradipine in cirrhotic patients had 37% oral bioavailability, but this small ionizable dihydropyridine is not representative of the query's large non-ionizable polyisoprenoid quinone, so its high-F direction has limited chemical transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a coenzyme Q10-type ubiquinone with an extremely long polyisoprenyl tail, very high logP, high molecular weight, and no ionizable groups. Direct human evidence for the structurally related isoprenoid lipid lycopene shows very low oral bioavailability (0.17–2.6%), and the physicochemical prior predicts poor absorption. High-transfer small-molecule drugs with moderate F are not representative of this lipophilic isoprenoid class. Therefore, F < 20% is better supported.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule (CoQ10) was provided.",
    "The closest structural analogue (lycopene) has a low assay-transfer score, so its quantitative F values may not directly extrapolate.",
    "High-transfer records are conventional small-molecule drugs with different physicochemical properties."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

